let lastEntryPick=null;
function manageEntries(id){
 lastEntryPick=null;
 if(!isAdmin()){toast('Administrator access required.');return;}
 const c=state.competitions.find(c=>c.id===id);if(!c){toast('Competition not found.');return;}
 if(c.status==='drawn'){toast('This draw is fixed. Create a new competition for new entries.');return;}
 const remaining=state.players.filter(p=>!c.entries.includes(p.id));
 modal('Manage entries',`<p class="form-hint">${e(c.name)} · ${c.entries.length} entered.</p><button class="button primary full" data-add-all-players="${c.id}" ${remaining.length?'':'disabled'}>Add all players</button><p class="form-hint">${remaining.length?`Adds the ${remaining.length} registered player${remaining.length===1?'':'s'} not yet entered. Existing entries are kept.`:`All ${state.players.length} registered players are entered.`}</p>${remaining.length?`<form id="entry-selection-form" data-id="${c.id}"><fieldset class="entry-player-fieldset"><legend>Select players to add</legend><p class="form-hint" id="entry-selection-help">Click or tap names to select players. Hold Shift and click to select a range.</p><div class="entry-player-list" id="entry-player-list" aria-describedby="entry-selection-help">${remaining.map(p=>`<label class="entry-player-row"><input type="checkbox" name="playerIds" value="${p.id}" data-entry-pick><span>${e(p.name)}</span></label>`).join('')}</div></fieldset><p class="form-hint" id="entry-selection-count" role="status" aria-live="polite">0 players selected</p><button class="button secondary full" id="add-selected-players" type="submit" disabled>Add selected players</button><p class="error" id="form-error" role="alert"></p></form>`:''}<ul class="manage-entry-list">${c.entries.map(id=>`<li><span>${e(name(id))}</span><button class="button secondary" data-remove-entry="${id}" data-from-competition="${c.id}">Remove</button></li>`).join('')}</ul>`);
}
function confirmDraw(id){const c=state.competitions.find(c=>c.id===id),odd=c.mode==='pairs'&&c.entries.length%2,minimum=c.mode==='pairs'?4:2,sides=c.mode==='pairs'?c.entries.length/2:c.entries.length;modal('Draw competition',`<p>${e(c.name)} · ${c.entries.length} entrants.</p><p class="form-hint">${c.mode==='pairs'?'Partners will be randomly assigned from this entry list. ':''}Drawing closes entries and fixes the entrants, partners and match lengths. Further entrants wait for the next competition.</p>${odd?'<p class="error">One more player needed. Add a reserve or reopen entries before drawing.</p>':c.entries.length<minimum?`<p class="error">At least ${minimum} players must enter.</p>`:`<p class="form-hint">${c.format==='league'?`${sides*(sides-1)/2} league fixtures. Everyone plays everyone once.`:`${sides} ${c.mode==='pairs'?'pairs':'players'} in the knockout draw.`}</p>`}<button class="button primary full" data-confirm-draw="${c.id}" ${odd||c.entries.length<minimum?'disabled':''}>Draw & close entries</button>${odd?`<button class="button secondary full spaced" data-entries="${c.id}">Add a reserve</button>`:''}`);}
function selectEntryPlayers(target,shiftKey=false){
 const boxes=[...($('#entry-player-list')?.querySelectorAll('[data-entry-pick]')||[])],index=boxes.indexOf(target);
 if(index<0)return;
 if(shiftKey&&lastEntryPick!==null){const start=Math.min(lastEntryPick,index),end=Math.max(lastEntryPick,index);for(let i=start;i<=end;i++)boxes[i].checked=target.checked;}
 else lastEntryPick=index;
 const count=boxes.filter(box=>box.checked).length;
 $('#entry-selection-count').textContent=`${count} player${count===1?'':'s'} selected`;
 $('#add-selected-players').disabled=count===0;
}
document.addEventListener('click',event=>{if(event.target.matches?.('[data-entry-pick]'))selectEntryPlayers(event.target,event.shiftKey);});
