 if(location.protocol==='file:'){toast('Use the published championship to share joining links.');return;}
 if(id&&!state.competitions.some(c=>c.id===id))id='';
 const c=state.competitions.find(c=>c.id===id),link=joiningLink(id),message=joiningMessage(id);
 modal('Share joining links',`<p class="form-hint">Share the general link, or choose one competition to preselect it. Pupils still confirm their own entries.</p><label>Joining page<select id="joining-link-target"><option value="" ${id?'':'selected'}>All competitions</option>${state.competitions.map(c=>`<option value="${e(c.id)}" ${c.id===id?'selected':''}>${e(joiningTitle(c))} · ${competitionStatusLabel(c)}</option>`).join('')}</select></label>${c&&c.status!=='open'?'<p class="entry-note">This competition is closed to new entries. Its link still shows its current status.</p>':''}<label>Joining link<input id="joining-link" value="${e(link)}" readonly></label><div class="joining-share-actions"><button class="button primary" data-copy-joining="${e(id)}">Copy link</button>${typeof navigator.share==='function'?`<button class="button secondary" data-native-joining="${e(id)}">${icon('share',16)} Share…</button>`:''}<a class="button secondary" href="https://wa.me/?text=${encodeURIComponent(message)}" target="_blank" rel="noopener noreferrer">WhatsApp</a><a class="button secondary" href="mailto:?subject=${encodeURIComponent('Wakefield Pool Championship'+(c?' — '+joiningTitle(c):''))}&body=${encodeURIComponent(message)}">Email</a></div><label>Message to send<textarea rows="5" readonly>${e(message)}</textarea></label><p class="form-hint">Links contain no PINs and do not grant administrator access. Give each pupil their PIN separately.</p>`);
